import{_ as e,o as r,c as a,ag as o}from"./chunks/framework.4s5LDCII.js";const f=JSON.parse('{"title":"成人骨质疏松症食养指南（2026年版）","description":"国家卫健委《成人骨质疏松症食养指南（2026年版）》可执行整理：补钙补维 D 的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人骨质疏松症食养指南（2026年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2026年版","published":"2026-04","source_url":"https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml","status":"现行","tags":["骨质疏松","骨骼健康","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人骨质疏松症食养指南（2026年版）》可执行整理：补钙补维 D 的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/osteoporosis-2026.md","filePath":"guides/osteoporosis-2026.md"}'),s={name:"guides/osteoporosis-2026.md"};function d(i,t,g,h,p,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="成人骨质疏松症食养指南-2026年版" tabindex="-1">成人骨质疏松症食养指南（2026年版） <a class="header-anchor" href="#成人骨质疏松症食养指南-2026年版" aria-label="Permalink to &quot;成人骨质疏松症食养指南（2026年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>骨质疏松症患者，以及绝经后女性、老年人等高风险人群及其家人（<a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=5" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>七条原则</strong>：均衡营养、摄入富含钙和维生素 D 的食物 → 荤素搭配、保证膳食蛋白质的质和量 → 食物多样、优选营养素密度高的食物 → 适度日晒、规律运动、保持健康体重 → 饮酒限量、限制含糖和高咖啡因食物 → 科学烹饪、避免高油高盐 → 选择适宜食药物质、因地因时因人施膳。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>钙</td><td>中老年 <strong>1000～1200mg</strong>（可耐受上限 2000mg），膳食争取 ≥1000mg</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>奶类</td><td><strong>300mL 以上</strong>（50 岁以上每天 240mL 牛奶，髋部骨折风险降低 8%）；乳糖不耐受者可选发酵乳制品 ≥300g</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蛋白质类食物</td><td>鱼、禽、蛋、瘦肉合计 <strong>120～150g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>水产品</td><td><strong>每周 280～525g</strong>（65 岁以上 280～350g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>畜禽肉</td><td><strong>每周 280～525g</strong>（65 岁以上 280～350g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>蛋类</td><td><strong>每周 280～350g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>大豆</td><td><strong>每周 105～175g</strong> 或相当量豆制品（65 岁以上约 105g/周）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>坚果</td><td><strong>每周 50～70g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>蔬菜</td><td><strong>300～500g</strong>（65 岁以上 300～450g），深色过半</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>水果</td><td><strong>200～350g</strong>（65 岁以上 200～300g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>体重（老年人）</td><td>BMI <strong>22.0～26.9</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买-🍚-吃" tabindex="-1">🛒 买 / 🍚 吃 <a class="header-anchor" href="#🛒-买-🍚-吃" aria-label="Permalink to &quot;🛒 买 / 🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>每天奶类 300mL 以上（低脂亦可）；乳糖不耐受选酸奶/奶酪等发酵乳制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>深绿叶菜、豆制品、芝麻酱等含钙食物常上桌</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>荤素搭配，保证蛋白质&quot;质和量&quot;（动物蛋白+大豆蛋白）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>优选营养素密度高的食物，食物多样</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>饮酒限量；限制含糖与咖啡因含量高的食物（浓茶、浓咖啡、碳酸饮料等）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>科学烹饪，避免高油高盐</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(六)</a></td></tr></tbody></table><h3 id="🌞-动-🩺-测与就医" tabindex="-1">🌞 动 / 🩺 测与就医 <a class="header-anchor" href="#🌞-动-🩺-测与就医" aria-label="Permalink to &quot;🌞 动 / 🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td><strong>适度日晒</strong>促进维生素 D 合成；规律运动；保持健康体重</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>高风险人群用附录6 风险评估工具自评，及时就医查骨密度</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=84" target="_blank" rel="noreferrer">附录6</a></td></tr><tr><td>按证型选食药物质，因地因时因人施膳</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=9" target="_blank" rel="noreferrer">三(七)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;补钙只要吃钙片&quot;</td><td>钙应尽可能通过膳食摄入 1000mg 以上，奶类是最好的天然钙源</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>&quot;老年人要越瘦越好&quot;</td><td>老年人 BMI 适宜范围为 22.0～26.9，保持健康体重</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=20" target="_blank" rel="noreferrer">附录2《食物选择》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=23" target="_blank" rel="noreferrer">附录3《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=29" target="_blank" rel="noreferrer">附录4《不同地区不同季节食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=80" target="_blank" rel="noreferrer">附录5《证型食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/osteoporosis-2026.pdf#page=84" target="_blank" rel="noreferrer">附录6《风险评估工具》</a></strong> · 附录1《诊断和低骨量判定方法》见原文。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2026 年版（现行）</td></tr><tr><td>印发时间</td><td>2026 年 4 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',20)])])}const u=e(s,[["render",d]]);export{f as __pageData,u as default};
